WITH filtered_customers AS (SELECT *, CONCAT_WS('-', email, country) AS email_country_key FROM customers WHERE age > 51 AND country IN ('DE', 'US', 'JP') AND signup_date > '2023-06-01'), customers_stats AS (SELECT city, DATE_FORMAT(signup_date, 'yyyy-MM') AS signup_month, COUNT(CASE WHEN country = 'UK' THEN 1 END) AS uk_count FROM filtered_customers GROUP BY city, DATE_FORMAT(signup_date, 'yyyy-MM')) SELECT * FROM customers_stats ORDER BY signup_month, 1
